"""Bounded teaching app; supported JSON pid_file option and graceful owner cleanup."""
import errno,json,os,pathlib,sys,threading
from http.server import BaseHTTPRequestHandler,HTTPServer
config=json.loads(pathlib.Path(sys.argv[1]).read_bytes());pidfile=pathlib.Path(config['pid_file']);own=str(os.getpid())
try:
    fd=os.open(pidfile,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    with os.fdopen(fd,'w') as stream:stream.write(own)
except OSError as error:
    print(json.dumps(dict(started=False,errno=error.errno,path=str(pidfile))),flush=True)
    raise SystemExit(73)
class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        data=b'ready' if self.path=='/health' else pathlib.Path(config['data_file']).read_bytes()
        self.send_response(200);self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
    def log_message(self,*args):pass
server=HTTPServer(('127.0.0.1',0),Handler);thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
try:
    print(json.dumps(dict(started=True,pid=os.getpid(),port=server.server_port,uid=os.geteuid())),flush=True)
    for line in sys.stdin:
        if line.strip()=='stop':break
finally:
    server.shutdown();server.server_close();thread.join(2)
    if pidfile.is_file() and pidfile.read_text()==own:pidfile.unlink()
